import{_ as t,C as o,o as l,c as i,j as a,a as e,E as p,a2 as r}from"./chunks/framework.BTSE7CIX.js";const _=JSON.parse('{"title":"01. 专属标注与元数据","description":"测试 VitePress v1 (1.6.4) 的 Frontmatter 宽松元数据、::: 自定义容器、可折叠块、GitHub Alerts 与内联 Badge 组件。","frontmatter":{"title":"01. 专属标注与元数据","description":"测试 VitePress v1 (1.6.4) 的 Frontmatter 宽松元数据、::: 自定义容器、可折叠块、GitHub Alerts 与内联 Badge 组件。","outline":[2,3]},"headers":[],"relativePath":"01-annotations.md","filePath":"01-annotations.md"}'),c={name:"01-annotations.md"},d={id:"_01-专属标注与元数据",tabindex:"-1"};function u(b,s,m,g,h,k){const n=o("Badge");return l(),i("div",null,[a("h1",d,[s[0]||(s[0]=e("01. 专属标注与元数据 ",-1)),p(n,{type:"tip",text:"vitepress@1.6.4"}),s[1]||(s[1]=e()),s[2]||(s[2]=a("a",{class:"header-anchor",href:"#_01-专属标注与元数据","aria-label":'Permalink to "01. 专属标注与元数据 <Badge type="tip" text="vitepress@1.6.4" />"'},"​",-1))]),s[3]||(s[3]=r(`<p>不同静态网站生成器对“提示框 / 标注（Callouts / Admonitions）”和页面元数据的语法约定存在显著分歧。本页使用统一语义的测试文本展示 <strong>VitePress v1 (<code>1.6.4</code>)</strong> 的原生表现。</p><h2 id="_1-frontmatter-元数据机制" tabindex="-1">1. Frontmatter 元数据机制 <a class="header-anchor" href="#_1-frontmatter-元数据机制" aria-label="Permalink to &quot;1. Frontmatter 元数据机制&quot;">​</a></h2><p>VitePress v1 采用<strong>宽松型 YAML Frontmatter</strong>：无需预先编写 Schema 文件即可自由读取任意自定义字段（通过 Vue 组合式 API <code>useData().frontmatter</code> 访问）。目录层级通过 <code>outline: [2, 3]</code> 控制。</p><ul><li><strong>当前页标题字段</strong>：<code>title: 01. 专属标注与元数据</code></li><li><strong>目录深度字段</strong>：<code>outline: [2, 3]</code></li><li><strong>内联徽章支持</strong>：在 Markdown 标题或正文中可直接使用内置全局组件 <code>&lt;Badge type=&quot;info&quot; text=&quot;Info&quot; /&gt;</code> <code>&lt;Badge type=&quot;warning&quot; text=&quot;Warning&quot; /&gt;</code> <code>&lt;Badge type=&quot;danger&quot; text=&quot;Danger&quot; /&gt;</code>。</li></ul><h2 id="_2-标准提示容器-triple-colon-containers" tabindex="-1">2. 标准提示容器（Triple-Colon Containers） <a class="header-anchor" href="#_2-标准提示容器-triple-colon-containers" aria-label="Permalink to &quot;2. 标准提示容器（Triple-Colon Containers）&quot;">​</a></h2><p>VitePress v1 使用 <code>::: &lt;类型&gt; [可选自定义标题]</code> 语法（<code>:::</code> 与类型名之间通常留一个空格，自定义标题直接跟在空格后）：</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>默认信息提示块：静态站点对比平台的每个子模块均独立维护 <code>main</code>（源码）与 <code>page</code>（构建产物）双分支，互不污染提交历史。</p></div><div class="tip custom-block"><p class="custom-block-title">性能优化建议（自定义标题）</p><p>在 VitePress v1 中，自定义标题直接写在 <code>::: tip </code> 之后的同一行文本中，无需方括号包裹。支持内部嵌套行内代码如 <code>cleanUrls: true</code> 与加粗强调。</p></div><div class="warning custom-block"><p class="custom-block-title">版本边界注意</p><p>注意区分关键字命名：VitePress 使用 <code>warning</code> 表示警告块，而 Astro Starlight 等基于 <code>remark-directive</code> 的框架通常使用 <code>caution</code>。</p></div><div class="danger custom-block"><p class="custom-block-title">不可逆分支覆盖警告</p><p>自动化流水线在向 <code>page</code> 分支推送构建产物时会启用 <code>force_orphan: true</code>，切勿在 <code>page</code> 分支直接手工修改代码！</p></div><h2 id="_3-原生可折叠详情容器-details-block" tabindex="-1">3. 原生可折叠详情容器（Details Block） <a class="header-anchor" href="#_3-原生可折叠详情容器-details-block" aria-label="Permalink to &quot;3. 原生可折叠详情容器（Details Block）&quot;">​</a></h2><p>VitePress v1 将可折叠块也统一纳入了 <code>:::</code> 容器语法，无需手写原生 HTML <code>&lt;details&gt;</code> 标签：</p><details class="details custom-block"><summary>点击展开查看 VitePress 容器语法源码结构</summary><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::: tip 性能优化建议（自定义标题）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">自定义标题直接跟在类型关键字空格后。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></details><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>除了代码块，折叠容器内同样支持列表、表格与数学公式 $f(x) = x^2 + 1$。</span></span>
<span class="line"><span>:::</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 4. GitHub 风格引用警报（GFM Alerts）兼容性</span></span>
<span class="line"><span></span></span>
<span class="line"><span>许多开发者习惯在 GitHub Markdown 中直接编写 \`&gt; [!NOTE]\` 语法。以下为未经任何改写的原始 GFM Alert 块在 VitePress v1 下的实测渲染结果：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; [!NOTE]</span></span>
<span class="line"><span>&gt; 这是一段标准的 GitHub Flavored Markdown \`[!NOTE]\` 警报文本。VitePress v1 原生支持将其解析为带样式的提示框。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; [!IMPORTANT]</span></span>
<span class="line"><span>&gt; 跨平台迁移 Markdown 文档时，是否原生兼容 \`&gt; [!IMPORTANT]\` 与 \`&gt; [!WARNING]\` 直接决定了旧文档的改造成本。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; [!CAUTION]</span></span>
<span class="line"><span>&gt; 若目标生成器未内置 GFM Alert 解析器，上方标记会退化为普通引用块并原样露出 \`[!CAUTION]\` 字符串。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div>`,14))])}const P=t(c,[["render",u]]);export{_ as __pageData,P as default};
